<?php
namespace App\Livewire;
use App\Models\Exam;use App\Models\GradingScale;use App\Models\Student;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class ExamResults extends Component{public string $examId='';protected function canManage():bool{return in_array(Auth::user()->role,['admin','academic_admin'],true);}public function publish():void{$exam=Exam::with(['term','papers'])->where('school_id',Auth::user()->school_id)->findOrFail($this->examId);if(!$this->canManage()||!$exam->term->isOpen())abort(403);$approved=DB::table('exam_paper_submissions')->whereIn('exam_paper_id',$exam->papers->pluck('id'))->where('status','approved')->count();if(!$exam->papers->count()||$approved!==$exam->papers->count()){session()->flash('error','Approve every subject paper before publishing results.');return;}$exam->update(['published_at'=>now(),'published_by'=>Auth::id(),'status'=>'published']);session()->flash('status','Results published for learners and parents.');}public function unpublish():void{$exam=Exam::with('term')->where('school_id',Auth::user()->school_id)->findOrFail($this->examId);if(!$this->canManage()||!$exam->term->isOpen())abort(403);$exam->update(['published_at'=>null,'published_by'=>null,'status'=>'draft']);session()->flash('status','Results returned to internal access only.');}public function render(){$school=Auth::user()->school;$term=$school->currentTerm();$exams=Exam::with(['schoolClass','papers.subject'])->where('school_id',$school->id)->when($term,fn($q)=>$q->where('term_id',$term->id))->get();$exam=$this->examId?Exam::with(['schoolClass','papers.subject','term'])->where('school_id',$school->id)->find($this->examId):null;$results=collect();if($exam){$papers=$exam->papers->filter(fn($paper)=>DB::table('exam_paper_submissions')->where('exam_paper_id',$paper->id)->value('status')==='approved');$scales=GradingScale::where('school_id',$school->id)->get();$students=Student::where('school_id',$school->id)->where('school_class_id',$exam->school_class_id)->where('status','active')->get();foreach($students as $student){$subjects=[];$total=0;$maximum=0;foreach($papers as $paper){$score=(float)(DB::table('exam_marks')->where(['exam_paper_id'=>$paper->id,'student_id'=>$student->id])->value('score')??0);$percentage=$paper->maximum_score?round(($score/$paper->maximum_score)*100,2):0;$scale=$scales->first(fn($s)=>$percentage>=$s->minimum_percentage&&$percentage<=$s->maximum_percentage);$subjects[]=['name'=>$paper->subject->name,'score'=>$score,'max'=>$paper->maximum_score,'percentage'=>$percentage,'grade'=>$scale?->grade??'-'];$total+=$score*$paper->weighting;$maximum+=$paper->maximum_score*$paper->weighting;}$results->push(['student'=>$student,'subjects'=>$subjects,'total'=>$total,'percentage'=>$maximum?round(($total/$maximum)*100,2):0]);}$results=$results->sortByDesc('total')->values()->map(function($row,$index)use($scales){$row['position']=$index+1;$scale=$scales->first(fn($s)=>$row['percentage']>=$s->minimum_percentage&&$row['percentage']<=$s->maximum_percentage);$row['grade']=$scale?->grade??'-';return $row;});}return view('livewire.exam-results',['term'=>$term,'exams'=>$exams,'exam'=>$exam,'results'=>$results,'canManage'=>$this->canManage(),'pageTitle'=>'Exam Results']);}}
